using Nafadh_Backend.DTOs;
using Nafadh_Backend.Enums;
using Nafadh_Backend.Models;
using Nafadh_Backend.Repositories;

namespace Nafadh_Backend.Services
{
    public class FeedbackService : IFeedbackService
    {
        private readonly IFeedbackRepository _repository;

        public FeedbackService(IFeedbackRepository repository)
        {
            _repository = repository;
        }

        public async Task<List<FeedbackCriterionDTO>> GetCriteriaAsync(NFD_FeedbackType? appliesTo)
        {
            var criteria = await _repository.GetCriteriaAsync(appliesTo);
            return criteria.Select(c => new FeedbackCriterionDTO
            {
                CriterionId = c.CriterionId,
                AppliesTo = c.AppliesTo,
                Name = c.Name,
                OrderIndex = c.OrderIndex
            }).ToList();
        }

        public async Task<FeedbackDTO> CreateFeedbackAsync(CreateFeedbackDTO dto)
        {
            var feedback = new NFD_Feedback
            {
                Type = dto.Type,
                TraineeId = dto.TraineeId,
                ModuleId = dto.ModuleId,
                TrainerId = dto.Type == NFD_FeedbackType.TrainerRating ? dto.TrainerId : null,
                BatchId = dto.Type == NFD_FeedbackType.BatchExperienceRating ? dto.BatchId : null,
                Comment = dto.Comment,
                SubmittedAt = DateTime.UtcNow,
                Scores = dto.Scores.Select(s => new NFD_FeedbackScore
                {
                    CriterionId = s.CriterionId,
                    Score = s.Score
                }).ToList()
            };

            var created = await _repository.AddFeedbackAsync(feedback);

            return new FeedbackDTO
            {
                FeedbackId = created.FeedbackId,
                Type = created.Type,
                TraineeId = created.TraineeId,
                ModuleId = created.ModuleId,
                TrainerId = created.TrainerId,
                BatchId = created.BatchId,
                Comment = created.Comment,
                SubmittedAt = created.SubmittedAt,
                Scores = dto.Scores
            };
        }

        public async Task<FeedbackSummaryDTO> GetTrainerSummaryAsync(int trainerId)
        {
            var feedbacks = await _repository.GetByTrainerAsync(trainerId);
            return Summarize(feedbacks);
        }

        public async Task<FeedbackSummaryDTO> GetBatchSummaryAsync(int batchId)
        {
            var feedbacks = await _repository.GetByBatchAsync(batchId);
            return Summarize(feedbacks);
        }

        public async Task<FeedbackPendingDTO> GetPendingAsync(int moduleId, int traineeId)
        {
            var trainerRatingSubmitted = await _repository.HasSubmittedAsync(traineeId, moduleId, NFD_FeedbackType.TrainerRating);
            var batchRatingSubmitted = await _repository.HasSubmittedAsync(traineeId, moduleId, NFD_FeedbackType.BatchExperienceRating);

            return new FeedbackPendingDTO
            {
                TrainerRatingPending = !trainerRatingSubmitted,
                BatchRatingPending = !batchRatingSubmitted
            };
        }

        private static FeedbackSummaryDTO Summarize(List<NFD_Feedback> feedbacks)
        {
            var allScores = feedbacks.SelectMany(f => f.Scores).ToList();

            var perCriterion = allScores
                .GroupBy(s => new { s.CriterionId, Name = s.Criterion?.Name })
                .Select(g => new FeedbackCriterionAverageDTO
                {
                    CriterionId = g.Key.CriterionId,
                    Name = g.Key.Name,
                    Average = g.Average(s => s.Score)
                })
                .ToList();

            return new FeedbackSummaryDTO
            {
                AverageOverall = allScores.Count > 0 ? allScores.Average(s => s.Score) : 0,
                PerCriterion = perCriterion,
                Comments = feedbacks
                    .Where(f => !string.IsNullOrWhiteSpace(f.Comment))
                    .Select(f => new FeedbackCommentDTO { Comment = f.Comment!, Date = f.SubmittedAt })
                    .OrderByDescending(c => c.Date)
                    .ToList(),
                ResponseCount = feedbacks.Count
            };
        }
    }
}
